	private static QueryResultCollector parse(TupleQueryResultParser parser, String input) throws Exception {
		QueryResultCollector collector = new QueryResultCollector();
		parser.setQueryResultHandler(collector);
		parser.parse(new ByteArrayInputStream(input.getBytes(StandardCharsets.UTF_8)));
		assertTrue(collector.getHandledTuple());
		return collector;
	}

