	private static void assertStreamsLargeGeneratedInput(TupleQueryResultParser parser, String header, String row)
			throws Exception {
		final int rowCount = 100_000;
		byte[] headerBytes = header.getBytes(StandardCharsets.UTF_8);
		byte[] rowBytes = row.getBytes(StandardCharsets.UTF_8);
		AtomicInteger generatedRows = new AtomicInteger();
		InputStream input = new InputStream() {
			private long position;
			private final long total = headerBytes.length + (long) rowBytes.length * rowCount;

			@Override
			public int read() {
				if (position == total) {
					return -1;
				}
				if (position < headerBytes.length) {
					return headerBytes[(int) position++] & 0xff;
				}
				int rowPosition = (int) ((position++ - headerBytes.length) % rowBytes.length);
				if (rowPosition == rowBytes.length - 1) {
					generatedRows.incrementAndGet();
				}
				return rowBytes[rowPosition] & 0xff;
			}

			@Override
			public int read(byte[] bytes, int offset, int length) {
				if (length == 0) {
					return 0;
				}
				int count = 0;
				while (count < length) {
					int next = read();
					if (next == -1) {
						break;
					}
					bytes[offset + count++] = (byte) next;
				}
				return count == 0 ? -1 : count;
			}
		};

		AtomicInteger started = new AtomicInteger();
		AtomicInteger delivered = new AtomicInteger();
		AtomicInteger ended = new AtomicInteger();
		parser.setQueryResultHandler(new QueryResultCollector() {
			@Override
			public void startQueryResult(List<String> names) {
				assertEquals(List.of("x"), names);
				started.incrementAndGet();
			}

			@Override
			public void handleSolution(BindingSet bindingSet) {
				assertEquals("http://example.org/row", bindingSet.getValue("x").stringValue());
				if (delivered.getAndIncrement() == 0) {
					assertTrue(generatedRows.get() < rowCount, "first callback must precede end of input");
				}
			}

			@Override
			public void endQueryResult() {
				ended.incrementAndGet();
			}
		});
		parser.parse(input);
		assertEquals(rowCount, generatedRows.get());
		assertEquals(rowCount, delivered.get());
		assertEquals(1, started.get());
		assertEquals(1, ended.get());
	}

	private static void assertFirstRowBeforeLaterInput(TupleQueryResultParser parser, String firstPart) {
		AtomicReference<List<String>> names = new AtomicReference<>();
		AtomicReference<String> value = new AtomicReference<>();
		AtomicBoolean ended = new AtomicBoolean();
		AtomicBoolean laterReadBeforeCallback = new AtomicBoolean();
		parser.setQueryResultHandler(new QueryResultCollector() {
			@Override
			public void startQueryResult(List<String> bindingNames) {
				names.set(List.copyOf(bindingNames));
			}

			@Override
			public void handleSolution(BindingSet bindingSet) throws TupleQueryResultHandlerException {
				value.set(bindingSet.getValue("x").stringValue());
				throw new TupleQueryResultHandlerException("stop after first row");
			}

			@Override
			public void endQueryResult() {
				ended.set(true);
			}
		});

		InputStream laterInput = new InputStream() {
			@Override
			public int read() throws IOException {
				if (value.get() == null) {
					laterReadBeforeCallback.set(true);
				}
				return -1;
			}

			@Override
			public int read(byte[] bytes, int offset, int length) throws IOException {
				if (value.get() == null) {
					laterReadBeforeCallback.set(true);
				}
				return -1;
			}
		};
		InputStream input = new SequenceInputStream(
				new ByteArrayInputStream(firstPart.getBytes(StandardCharsets.UTF_8)), laterInput);

		TupleQueryResultHandlerException stop = assertThrows(TupleQueryResultHandlerException.class,
				() -> parser.parse(input));
		assertEquals("stop after first row", stop.getMessage());
		assertEquals(List.of("x"), names.get());
		assertEquals("http://example.org/first", value.get());
		assertFalse(ended.get());
		assertFalse(laterReadBeforeCallback.get(), "later input was read before the first row callback");
	}
